	public String applyTaxDSC(String status) {
    String ipAddress = "127.0.0.1"; // IP address of the server
    int port = 1620; // Port number of the server

    try {
    	log.debug("URL creating object and initilaizing connectionn.....");
        URL url = new URL("http://" + ipAddress + ":" + port);
        HttpURLConnection connection = (HttpURLConnection) url.openConnection();
    	log.debug("Connection Open.....");
    	 connection.setRequestMethod("POST");
         connection.setRequestProperty("Content-Type", "application/xml");
         connection.setRequestProperty("Connection", "keep-alive");
         connection.setDoOutput(true);
    	log.debug("Writing data to Outputstram using cnnection.....XXXXXXXXXX");

        try (OutputStream os = connection.getOutputStream()) {
            byte[] input = status.getBytes("utf-8");
            os.write(input, 0, input.length);
        }
        log.debug("Data written.....XXXXXXXXXX");
        try (BufferedReader br = new BufferedReader(new InputStreamReader(connection.getInputStream(), "utf-8"))) {
            StringBuilder response = new StringBuilder();
            String responseLine = null;
            log.debug("Response is reading....XXXXXXXXXX");
            while ((responseLine = br.readLine()) != null) {
                response.append(responseLine.trim());
                log.debug("Response is stored in StringBuilder....XXXXXXXXXX");

            }
            System.out.println("Response: " + response.toString());
            log.debug("Response....XXXXXXXXXX"+ response.toString());

            return response.toString();
        }
    } catch (IOException e) {
    	e.getMessage();
        System.err.println("Error: " + e.getMessage());
        return null;
    }
}
	
	
